const MAX_TURBO = 50; // depending on (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))
const FS = 24;
let TS, FX, FY;
let screen = [], blocks = [], blockIndex = 0, blockMinSize = 3, blockProgress = 3 * blockMinSize;

let palIndex;
const palette = [
	["white", "white", "white", "white", "white", "white", "pink", "pink", "pink", "pink", "pink", "salmon", "salmon", "salmon", "CornflowerBlue", "CornflowerBlue", "teal"],
	["white", "white", "white", "gray", "gray", "black"],
	["white", "white", "black"],
	["white", "white", "white", "lightblue", "lightblue", "darkred"]
];

function setup() {
	// createCanvas(S = max(windowWidth, windowHeight), S);
	createCanvas(windowWidth, windowHeight);
	FX = FS; FY = FS;
	if (width > height) {
		FX = floor(width * FS / height);
	} else {
		FY = floor(height * FS / width);
	}
	FX++; FY++;
	TS = width / FX;

	background("white")
	frameRate(5);
	pixelDensity(1);

	blocks = [];
	if (true) {
		palIndex = floor(random(palette.length));
		generateBlocks();

	} else {
		addBlocks(["pink", "white", "CornflowerBlue"], 10);
		addBlocks(["white", "white", "CornflowerBlue", "white", "CornflowerBlue"], 10);
		addBlocks(["white"], 15);
		addBlocks(["pink", "pink", "pink", "CornflowerBlue", "CornflowerBlue", "white", "white"], 5);
		addBlocks(["salmon", "salmon", "CornflowerBlue", "salmon", "salmon", "CornflowerBlue", "salmon"]);
		addBlocks(["CornflowerBlue", "CornflowerBlue", "teal"], 30);
		addBlocks(["pink"], 60);
		addBlocks(["CornflowerBlue", "pink", "white"], 20);
	}

	screen = [];
	addBlockToScreen(floor(FX * FY) + 1);

	// console.log(">init: ", TS, FS, FX, FY, blocks.length, screen.length)
}

function mousePressed() {
	setup();
	// if (isLooping()) { // noLoop() removed for animation } else { loop(); }
}

function addBlocks(arr, n = 1) {
	for (let i = 0; i < n; i++) {
		blocks = blocks.concat(arr);
	}
}

function generateBlocks() {
	const numBlocks = floor(random(5, 15));
	for (let i = 0; i < numBlocks; i++) {
		let [arr, num] = generateBlock();
		addBlocks(arr, num);
	}
}

function generateBlock() {
	let num = floor(random(5, 15)) * blockMinSize;
	if (random() < 0.1) num = 1;

	let arr = [];
	const arrLen = floor(random(blockMinSize, 5 * blockMinSize));
	for (let i = 0; i < arrLen; i++) {
		const clrI = floor(random(palette[palIndex].length));
		arr.push(clrI); // random(clrs)
	}

	return [arr, num];
}


function addBlockToScreen(turbo = 1) {
	// for (let i = 0; i < blockProgress * turbo; i++) {
	for (let i = 0; i < turbo; i++) {
		screen.unshift(blocks[blockIndex]); // insert at the beginning
		blockIndex = (blockIndex + 1) % blocks.length;
	}
	if (screen.length > FX * FY) {
		screen.splice(FX * FY);
	}
}

function draw() {
	background("white");
	noStroke();

	// add blocks to screen
	const turbo = max(1, min(MAX_TURBO, (map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 1, MAX_TURBO))));
	addBlockToScreen(turbo);

	// console.log(screen.length, screen[0])

	// print out
	let i = 0;
	const TS1 = floor(TS);
	const TS2 = TS1 + 1;
	for (let y = 0; y < FY; y++) {
		for (let x = 0; x < FX; x++) {
		// for (let x = FX - 1; x >= 0; x--) {
			if (i < screen.length) {
				fill(palette[palIndex][screen[i]])
				rect(x * TS1, y * TS1, TS2, TS2);
			}
			i++;
		}
	}
}
